import React, { useState } from 'react';
import Tesseract from 'tesseract.js';
import './App.css';

function App() {
  const [image, setImage] = useState(null);
  const [ocrText, setOcrText] = useState('');
  const [sceneText, setSceneText] = useState('');
  const [loading, setLoading] = useState(false);
  const [results, setResults] = useState(null);

  const handleImageChange = (e) => {
    if (e.target.files[0]) {
      setImage(e.target.files[0]);
      setOcrText('');
      setSceneText('');
    }
  };

  const handleOcr = async () => {
    if (!image) return;
    setLoading(true);
    const { data } = await Tesseract.recognize(image, 'por');
    setOcrText(data.text);
    setSceneText(data.text);
    setLoading(false);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    const response = await fetch('http://localhost:5000/search', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ text: sceneText })
    });
    const data = await response.json();
    setResults(data);
    setLoading(false);
  };

  return (
    <div className="app-container">
      <h1>ShotFinder</h1>
      <form onSubmit={handleSubmit}>
        <div style={{ marginBottom: 18 }}>
          <label>Upload de imagem:</label><br />
          <input type="file" accept="image/*" onChange={handleImageChange} />
          <button type="button" onClick={handleOcr} disabled={!image || loading} style={{ marginLeft: 8 }}>
            {loading ? 'Processando...' : 'Extrair texto (OCR)'}
          </button>
        </div>
        <div style={{ marginBottom: 18 }}>
          <label>Ou descreva a cena:</label><br />
          <textarea
            rows={4}
            value={sceneText}
            onChange={e => setSceneText(e.target.value)}
            placeholder="Ex: Um homem com capa preta luta contra vilões em uma cidade escura."
          />
        </div>
        <button type="submit" disabled={!sceneText || loading} style={{ width: '100%' }}>
          {loading ? 'Buscando...' : 'Buscar filme/série'}
        </button>
      </form>
      {ocrText && (
        <div className="ocr-preview">
          <strong>Texto extraído da imagem:</strong>
          <div style={{ marginTop: 4 }}>{ocrText}</div>
        </div>
      )}
      {results && (
        <div className="resultados">
          <h2 style={{ textAlign: 'center', color: '#1e293b', fontSize: '1.3rem', marginBottom: 18 }}>Resultados:</h2>
          {results.length === 0 && <p style={{ textAlign: 'center' }}>Nenhum resultado encontrado.</p>}
          {results.map((item) => (
            <div key={item.id} className="result-card">
              <img src={item.poster} alt={item.title} />
              <div className="result-info">
                <h3>{item.title} {item.year && <span style={{ color: '#64748b', fontWeight: 400 }}>({item.year})</span>}</h3>
                <p><strong>Sinopse:</strong> {item.overview}</p>
                <p><strong>Elenco:</strong> {item.cast}</p>
                <p><strong>Onde assistir:</strong> {item.streaming && item.streaming.length > 0 ? item.streaming.join(', ') : 'Não encontrado'}</p>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

export default App;
